describe('startCountdown', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test('should not call callback before delay has passed', () => {
    const callback = jest.fn();
    startCountdown(callback, 1000);

    jest.advanceTimersByTime(999);

    expect(callback).not.toHaveBeenCalled();
  });

  test('should call callback after delay has passed', () => {
    const callback = jest.fn();
    startCountdown(callback, 1000);

