import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { UserProfile } from './UserProfile';

jest.mock('fetch');

const mockUserData = {
  id: 1,
  name: 'John Doe',
  email: 'john@example.com'
};

describe('UserProfile Component', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('should display loading state initially', async () => {
    global.fetch = jest.fn(() =>
      new Promise(resolve =>
        setTimeout(() => resolve({
          ok: true,
          json: async () => mockUserData
        }), 100)
      )
    );

    render(<UserProfile />);
    expect(screen.getByRole('progressbar')).toBeInTheDocument();

    await waitFor(() => {
      expect(screen.queryByRole('progressbar')).not.toBeInTheDocument();
    });
  });

  test('should display user data after successful fetch', async () => {
    global.fetch = jest.fn(() =>
      Promise.resolve({
        ok: true,
        json: async () => mockUserData
      })
    );

    render(<UserProfile />);

    await waitFor(() => {
      expect(screen.getByText('John Doe')).toBeInTheDocument();
      expect(screen.getByText('john@example.com')).toBeInTheDocument();
    });
  });

  test('should handle form submission for profile update', async () => {
    global.fetch = jest.fn()
      .mockResolvedValueOnce({
        ok: true,
        json: async () => mockUserData
      })
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({ ...mockUserData, name: 'Jane Doe' })
      });

    const user = userEvent.setup();
    render(<UserProfile />);

    await waitFor(() => {
      expect(screen.getByText('John Doe')).toBeInTheDocument();
    });

    const nameInput = screen.getByDisplayValue('John Doe');
    await user.clear(nameInput);
    await user.type(nameInput, 'Jane Doe');
    await user.click(screen.getByRole('button', { name: /save/i }));

    await waitFor(() => {
      expect(screen.getByText(/success/i)).toBeInTheDocument();
    });
  });

  test('should display error message on fetch failure', async () => {
    global.fetch = jest.fn(() =>
      Promise.resolve({
        ok: false,
        status: 500
      })
    );

    render(<UserProfile />);

    await waitFor(() => {
      expect(screen.getByText(/error loading user/i)).toBeInTheDocument();
    });
  });
});

description.en:
Write a test suite for a custom hook `useUserForm` that manages form state and validation. The hook should:

1. Track form field values (name, email, password)
2. Validate fields with custom rules
3. Provide methods to update fields and reset form
4. Return validation errors for each field
5. Track form dirty state and submission status

The hook signature:
typescript
interface FormState {
  values: { name: string; email: string; password: string };
  errors: { name?: string; email?: string; password?: string };
  isDirty: boolean;
  isSubmitting: boolean;
}

function useUserForm(initialValues?: Partial<FormState['values']>): {
  formState: FormState;
  setFieldValue: (field: string, value: string) => void;
  resetForm: () => void;
  submitForm: (callback: () => Promise<void>) => Promise<void>;
}


**Example usage:**
- Initial state has empty values and no errors
- Setting a field value marks form as dirty
- Validation runs on field change (email format, password strength)
- Reset clears values and errors, sets isDirty to false
- submitForm sets isSubmitting to true during async operation

**Test cases to cover:**
1. Hook initializes with correct default state
2. setFieldValue updates form values and marks dirty
3. Field validation shows appropriate errors
4. resetForm clears all data and state
5. submitForm manages loading state during async operation
6. Multiple field updates work correctly

